package sssm.dev.sssm_backend.a11_inventory.item_category.service;
import java.util.*; import sssm.dev.sssm_backend.a11_inventory.item_category.entity.ItemCategory; import sssm.dev.sssm_backend.a11_inventory.item_category.repository.*;
public class ItemCategoryService { private final ItemCategoryDAO dao=new ItemCategoryDAOImpl(); public List<ItemCategory> findAll(Optional<String> q,Optional<Integer> p,Optional<Integer> s){int page=p.orElse(1),size=s.orElse(10);return q.isPresent()?dao.search(q.get(),page,size):dao.findAll(page,size);} public Optional<ItemCategory> findById(String id){return dao.findById(id);} public ItemCategory create(ItemCategory v){return dao.create(v);} public ItemCategory update(String id,ItemCategory v){if(dao.findById(id).isEmpty())throw new IllegalArgumentException("ItemCategory not found with ID: "+id);v.setId(id);return dao.update(v);} public void delete(String id){dao.delete(id);} }
